    for (int i = 0; i < 4; ++i) {
        points[i] = rt.weighted_point(c, i);
    }

    // Extract coordinates and weights
    std::array<double, 4> x, y, z, w;
    for (int i = 0; i < 4; ++i) {
        x[i] = points[i].x();
        y[i] = points[i].y();
        z[i] = points[i].z();
        w[i] = points[i].weight();
    }

    // Compute the 4D lifted coordinates: (x, y, z, x²+y²+z²-w)
    std::array<double, 4> lifted[4];
    for (int i = 0; i < 4; ++i) {
        double r2 = x[i]*x[i] + y[i]*y[i] + z[i]*z[i];
        lifted[i][0] = x[i];
        lifted[i][1] = y[i];
        lifted[i][2] = z[i];
        lifted[i][3] = r2 - w[i];
    }

    // Compute the normal vector to the hyperplane in 4D
    // This is the cross product of three vectors in 4D
    // We compute the determinant of a 4x4 matrix where each row is a difference vector
    // and the last column is all ones (for the homogeneous coordinates)

    // Create three vectors from the first point to the others
    double v1[3], v2[3], v3[3];
    double w1[3], w2[3], w3[3];

    for (int i = 0; i < 3; ++i) {
        v1[i] = lifted[1][i] - lifted[0][i];
        v2[i] = lifted[2][i] - lifted[0][i];
        v3[i] = lifted[3][i] - lifted[0][i];
        w1[i] = lifted[1][3] - lifted[0][3];
        w2[i] = lifted[2][3] - lifted[0][3];
        w3[i] = lifted[3][3] - lifted[0][3];
    }

    // The normal vector components are the determinants of 3x3 minors
    // We need to compute the 4D cross product
    double nx = v1[1]*(v2[2]*w3[0] - v2[0]*w3[2]) - v1[2]*(v2[1]*w3[0] - v2[0]*w3[1]) + w1[0]*(v2[1]*v3[2] - v2[2]*v3[1]);
    double ny = v1[2]*(v2[0]*w3[1] - v2[1]*w3[0]) - v1[0]*(v2[2]*w3[1] - v2[1]*w3[2]) + w1[1]*(v2[2]*v3[0] - v2[0]*v3[2]);
    double nz = v1[0]*(v2[1]*w3[2] - v2[2]*w3[1]) - v1[1]*(v2[0]*w3[2] - v2[2]*w3[0]) + w1[2]*(v2[0]*v3[1] - v2[1]*v3[0]);

    // The velocity vector is proportional to the normal vector
    // Scale by time parameter as velocity = displacement/time
    if (time > 1e-10) {
        nx /= time;
        ny /= time;
        nz /= time;
    }

    return Vector(nx, ny, nz);

